def check(n):
    # Check if 2n-1 divides 3((n+2)! + 1)
    if n < 0:
        return False

    divisor = 2*n - 1
    if divisor == 0:
        return False

    dividend = 3 * (math.factorial(n + 2) + 1)

    if dividend % divisor == 0:
        return True
    else:
        return False

import math

# Test small values
for n in range(6):
    print(f"n={n}: {check(n)}")

# Test n=10
print(f"n=10: {check(10)}")

